contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 n, address a) public payable {
        require(n >= 1 && n <= 3, "n out of bounds");
        require(a != address(0), "zero address");

        uint256 before = c.getNodeDelegatorQueue().length;
        require(before + n <= c.maxNodeDelegatorCount(), "not enough capacity");

        address[] memory ndcs = new address[](n);
        for (uint256 i = 0; i < n; ++i) {
            ndcs[i] = a;
        }

        c.addNodeDelegatorContractToQueue(ndcs);

        uint256 afterLen = c.getNodeDelegatorQueue().length;
        assert(afterLen == before + n);
    }

    receive() external payable {}
}

