contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 depositAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");

        c.initialize(address(this));
        require(c.maxNodeDelegatorCount() == 10, "initial maxNodeDelegatorCount mismatch");

        (bool ok, bytes memory ret) = asset.staticcall(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, address(this), depositAmount)
        );
        require(ok && ret.length >= 32 && abi.decode(ret, (bool)), "asset transferFrom setup failed");

        uint256 beforeMint = c.getRsETHAmountToMint(asset, depositAmount);

        c.depositAsset(asset, depositAmount);

        uint256 poolBalance = IERC20Min(asset).balanceOf(address(c));

        assert(
            IERC20Min(asset).allowance(msg.sender, address(c)) >= depositAmount &&
            IERC20Min(asset).balanceOf(msg.sender) == 0 &&
            poolBalance == depositAmount &&
            c.getTotalAssetDeposits(asset) == depositAmount &&
            c.getAssetCurrentLimit(asset) == type(uint256).max - depositAmount &&
            beforeMint >= 0
        );
    }

    receive() external payable {}
}

interface IERC20Min {
    function balanceOf(address) external view returns (uint256);
    function allowance(address, address) external view returns (uint256);
}

