contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, address ndc1, address ndc2) public payable {
        require(true);

        // --- setup: build a non-trivial queue of node delegators on c ---
        address[] memory queue = new address[](2);
        queue[0] = ndc1;
        queue[1] = ndc2;

        bool added;
        try c.addNodeDelegatorContractToQueue(queue) {
            added = true;
        } catch {
            added = false;
        }

        // --- read values from c through its public surface ---
        uint256 totalAssets = c.getTotalAssetDeposits(asset);

        uint256 lyingInDepositPool;
        uint256 lyingInNDCs;
        uint256 stakedInEigenLayer;
        try c.getAssetDistributionData(asset) returns (uint256 a, uint256 b, uint256 d) {
            lyingInDepositPool = a;
            lyingInNDCs = b;
            stakedInEigenLayer = d;
        } catch {
            lyingInDepositPool = 0;
            lyingInNDCs = 0;
            stakedInEigenLayer = 0;
        }

        // --- general rule for whichever asset is supported ---
        if (lyingInDepositPool != 0 || lyingInNDCs != 0 || stakedInEigenLayer != 0) {
            assert(totalAssets == lyingInDepositPool + lyingInNDCs + stakedInEigenLayer);
        } else {
            // if the asset is not supported and the aggregate getter reverted, it must return 0 on read
            assert(totalAssets == 0);
        }
    }

    receive() external payable {}
}

