            require(okR2);
            afterRsethBal = abi.decode(data, (uint256));
        }

        uint256 expectedMint = (depositAmount * assetPrice) / rsethPrice;

        assert(
            reverted
                ? (afterCBal == beforeCBal &&
                   afterCallerAssetBal == beforeCallerAssetBal &&
                   afterRsethBal == beforeRsethBal)
                : (afterCBal == beforeCBal + depositAmount &&
                   afterCallerAssetBal == beforeCallerAssetBal - depositAmount &&
                   afterRsethBal == beforeRsethBal + expectedMint)
        );
    }

    receive() external payable {}
}

