contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset) public payable {
        bool reverted;
        uint256 limit;
        uint256 deposits;

        // Ensure the asset is supported so getAssetCurrentLimit's external calls don't revert
        // for an unsupported-asset reason. lrtConfig must already be set on c at deployment.
        bool supported = ILRTConfig(c.lrtConfig()).isSupportedAsset(asset);
        require(supported, "asset not supported");

        uint256 configuredLimit = ILRTConfig(c.lrtConfig()).depositLimitByAsset(asset);

        try c.getTotalAssetDeposits(asset) returns (uint256 d) {
            deposits = d;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            try c.getAssetCurrentLimit(asset) returns (uint256 l) {
                limit = l;
            } catch {
                reverted = true;
            }
        }

        // The general rule: whenever getAssetCurrentLimit succeeds, its value equals
        // the configured deposit limit minus the total asset deposits.
        // If the subtraction would underflow, the call must revert.
        if (reverted) {
            assert(configuredLimit < deposits);
        } else {
            assert(limit == configuredLimit - deposits);
        }
    }

    receive() external payable {}
}

