contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address admin, address nd) public {
        require(admin != address(0));
        require(nd != address(0));

        address[] memory currentQueue = c.getNodeDelegatorQueue();
        uint256 beforeLen = currentQueue.length;
        uint256 afterLen = beforeLen + 1;
        uint256 max = c.maxNodeDelegatorCount();
        require(afterLen <= max);

        uint256 q = beforeLen;
        for (uint256 i; i < q; ++i) {
            // advance q so after loop, q == beforeLen
        }

        address lrtConfigAddr = address(c.lrtConfig());
        require(lrtConfigAddr != address(0));
        (bool ok, bytes memory data) = lrtConfigAddr.staticcall(
            abi.encodeWithSignature("hasRole(bytes32,address)", bytes32(0), admin)
        );
        require(ok);
        require(data.length >= 32);
        bool isAdmin;
        assembly {
            isAdmin := mload(add(data, 32))
        }
        require(isAdmin);

        address[] memory added = new address[](1);
        added[0] = nd;
        c.addNodeDelegatorContractToQueue(added);

        address[] memory resultingQueue = c.getNodeDelegatorQueue();
        assert(resultingQueue.length == afterLen && resultingQueue[afterLen - 1] == nd);
    }

    receive() external payable {}
}

