    }

    function run(uint256 newMax, address ndc) public payable {
        require(ndc != address(0));

        address[] memory one = new address[](1);
        one[0] = ndc;

        // First add one node delegator to the queue (as the deployer, which is the LRT admin
        // in the fresh deployment).
        c.addNodeDelegatorContractToQueue(one);

        uint256 queueLenBefore = c.getNodeDelegatorQueue().length;
        require(queueLenBefore == 1);

        // Now lower the max count below the current queue length.
        c.updateMaxNodeDelegatorCount(newMax);

        // The existing queue must not be truncated by lowering the max.
        uint256 queueLenAfter = c.getNodeDelegatorQueue().length;

        address[] memory two = new address[](1);
        two[0] = ndc;

        bool added;
        try c.addNodeDelegatorContractToQueue(two) { added = true; } catch { added = false; }

        // If the new max is strictly less than the current queue length, adding another
        // delegator must revert and the queue length must be unchanged.
        assert(newMax >= queueLenAfter ? added : (!added && queueLenAfter == queueLenBefore));
    }

    receive() external payable {}
}

