contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 ndcIndex, uint256 amount) public payable {
        require(asset != address(0), "asset zero");

        // setup: make the asset a supported asset, because the transfer function
        // reverts for unsupported assets and the rule only applies to supported assets
        bool addedSupportedAsset;
        try c.addSupportedAsset(asset) { addedSupportedAsset = true; } catch { addedSupportedAsset = false; }
        require(addedSupportedAsset, "setup failed");

        // setup: add one non-zero node delegator so ndcIndex = 0 is valid
        address[] memory ndc = new address[](1);
        ndc[0] = address(0xdead);
        c.addNodeDelegatorContractToQueue(ndc);

        // setup: fund the deposit pool with the test asset
        require(IERC20(asset).mint(address(c), amount), "mint failed");

        uint256 balanceBefore = IERC20(asset).balanceOf(address(c));

        // deciding call: transfer `amount` asset from the deposit pool to nodeDelegatorQueue[ndcIndex]
        bool reverted;
        try c.transferAssetToNodeDelegator(ndcIndex, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = IERC20(asset).balanceOf(address(c));

        // general rule: if the transfer does not revert, then the deposit pool's
        // balance after the call is exactly its prior balance minus the amount sent.
        // This holds for every amount and input, and fails for a faulty version that
        // transfers the wrong amount or reports success without moving the asset.
        if (!reverted) {
            assert(balanceAfter == balanceBefore - amount);
        }
    }

    receive() external payable {}

    fallback() external payable {}
}

