        bool allFound = true;
        for (uint256 i = 0; i < newDelegators.length; i++) {
            address expected = newDelegators[i];
            bool found = false;
            for (uint256 j = initialLen; j < c.nodeDelegatorQueue.length(); j++) {
                if (c.nodeDelegatorQueue(j) == expected) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                allFound = false;
                break;
            }
        }

        assert(allFound && c.nodeDelegatorQueue.length() == initialLen + newDelegators.length);
    }

    receive() external payable {}
}

